def db_path_for(repo_path: str) -> Path:
    """某專案對應的 SQLite 庫檔路徑。"""
    return default_db_dir() / f"{project_key(repo_path)}.db"

def file_content_hash(path: str) -> str:
    """檔案內容 sha256（增量的失效 key）。"""
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(65536), b""):
            h.update(chunk)
    return h.hexdigest()

