    """取符號。給 file_path 只取該檔，否則取全專案。"""
    if file_path is not None:
        rows = self.conn.execute(
            "SELECT path,kind,name,line,end_line,scope FROM symbols "
            "WHERE path=? ORDER BY line", (file_path,)
        ).fetchall()
    else:
        rows = self.conn.execute(
            "SELECT path,kind,name,line,end_line,scope FROM symbols "
            "ORDER BY path,line"
        ).fetchall()
    return [dict(r) for r in rows]

