def _setup_chain(tmp_path):
    """leaf <- mid <- top 三層呼叫鏈；建全圖（對每符號 persist refs 邊）。"""
    _write(tmp_path, "m.py", """
        def leaf():
            return 1


        def mid():
            return leaf()


        def top():
            return mid()
    """)
    root = str(tmp_path)
    engine.index_project(root)
    for sym in ("leaf", "mid", "top"):
        engine.find_references(root, sym, src_root=root, persist=True)
    return root

