    _write(project, "m.go", '''
        package main
        func handle1(x int) int {
            switch x {
            case 1:
                return 10
            case 2:
                return 20
            default:
                return 99
            }
        }
        func handle2(x int) int {
            switch x {
            case 1:
                return 10
            case 2:
                return 20
            default:
                return 99
            }
        }
    ''')
